import{_ as t,o as d,c as o,ae as r}from"./chunks/framework.YL6nI5ZP.js";const m=JSON.parse('{"title":"Scripts, Benchmarks & Verification","description":"","frontmatter":{},"headers":[],"relativePath":"reference/07-scripts-and-benchmarks.md","filePath":"reference/07-scripts-and-benchmarks.md"}'),s={name:"reference/07-scripts-and-benchmarks.md"};function n(a,e,c,i,h,l){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="scripts-benchmarks-verification" tabindex="-1">Scripts, Benchmarks &amp; Verification <a class="header-anchor" href="#scripts-benchmarks-verification" aria-label="Permalink to &quot;Scripts, Benchmarks &amp; Verification&quot;">​</a></h1><p>The 15 <code>.mjs</code> scripts in <code>scripts/</code> plus the two shell build scripts — what each does and how to run it.</p><p>All run from the repo root with <code>node scripts/&lt;name&gt;.mjs</code>. The common pattern: shim <code>globalThis.self/window</code>, load <code>public/openswmm2d.js</code>, instantiate <code>openswmm2d.wasm</code> synchronously in Node, wrap the C API with <code>Module.cwrap</code>. Several spawn <code>server.py</code> + a Chrome instance via CDP.</p><h2 id="benchmarks-probes-engine-in-node" tabindex="-1">Benchmarks &amp; probes (engine in Node) <a class="header-anchor" href="#benchmarks-probes-engine-in-node" aria-label="Permalink to &quot;Benchmarks &amp; probes (engine in Node)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Purpose</th><th>Usage</th></tr></thead><tbody><tr><td><code>bench-1d-bellinge.mjs</code></td><td>Per-stride / per-window / freeze / cplF costs on Bellinge; projects 48 h wall time</td><td>no args</td></tr><tr><td><code>bench-1d.mjs</code></td><td>Bare 1D stride benchmark; JSON output</td><td><code>node bench-1d.mjs &lt;inp&gt; [--wasm &lt;path&gt;] [--tag &lt;l&gt;] [--keep-vs]</code></td></tr><tr><td><code>probe-1d.mjs</code></td><td>Per-step junction head/depth dump (capped 80 steps)</td><td><code>node probe-1d.mjs &lt;inp&gt;</code></td></tr><tr><td><code>probe-1d-coupl.mjs</code></td><td>Split-like 1D load: <code>setPondArea</code> + alternating <code>setLatInflow</code>; dt histogram</td><td>no args (Bellinge fixture)</td></tr><tr><td><code>probe-1d-nan.mjs</code></td><td>Full 48 h 1D run scanning heads/depths/volumes for NaN/Inf</td><td><code>node probe-1d-nan.mjs [VS]</code></td></tr><tr><td><code>probe-cpl.mjs</code></td><td>Per-stride coupling volume deltas from the 10-slot mass-balance buffer</td><td><code>node probe-cpl.mjs &lt;inp&gt;</code></td></tr><tr><td><code>run-engine-marcher.mjs</code></td><td>Reference 2D run: per-frame depth/head/velocity + node heads + mass balance → JSON. Requires a <strong>non-threaded</strong> wasm build (the threaded build needs a browser)</td><td><code>node run-engine-marcher.mjs &lt;inp&gt; &lt;out.json&gt; [--frames N] [--interval &lt;sec&gt;] [--wasm &lt;p&gt;]</code></td></tr><tr><td><code>bench-wasm-threads.mjs</code></td><td><strong>Threaded-engine gate:</strong> runs the production <code>openSwmm2dWorker.js</code> in cross-origin-isolated Chrome at THREADS 1 vs N; reports wall time + bit-identical continuity</td><td>CDP 9225</td></tr></tbody></table><h2 id="synthetic-input-generators" tabindex="-1">Synthetic input generators <a class="header-anchor" href="#synthetic-input-generators" aria-label="Permalink to &quot;Synthetic input generators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Purpose</th><th>Usage</th></tr></thead><tbody><tr><td><code>make-marcher-inp.mjs</code></td><td>M1 closed-basin 2D INP (WALL boundaries, sine-bed)</td><td><code>node make-marcher-inp.mjs &lt;nx&gt; &lt;ny&gt; &lt;dx&gt; &lt;rainMmHr&gt; &lt;min&gt; &lt;out.inp&gt;</code></td></tr><tr><td><code>make-marcher-cpl-inp.mjs</code></td><td>M2 1D↔2D coupling INP (storage S1 + conduit + outfall, cell 0 coupled)</td><td><code>node make-marcher-cpl-inp.mjs &lt;out.inp&gt;</code></td></tr></tbody></table><h2 id="chrome-cdp-end-to-end-harnesses" tabindex="-1">Chrome/CDP end-to-end harnesses <a class="header-anchor" href="#chrome-cdp-end-to-end-harnesses" aria-label="Permalink to &quot;Chrome/CDP end-to-end harnesses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Purpose</th><th>Port</th><th>Usage</th></tr></thead><tbody><tr><td><code>verify-bellinge.mjs</code></td><td><strong>Flagship gate:</strong> headless Chrome loads the app, projects Bellinge to EPSG:25832, auto-loads <code>Bellinge2.tif</code>, generates the mesh, runs the whole 48 h model through the app&#39;s own worker, asserts frames/depths/mass-balance/continuity</td><td>CDP 9222</td><td>no args; writes <code>scripts/verify-out/</code></td></tr><tr><td><code>verify-1d-split.mjs</code></td><td>Regression gate for the split&#39;s 1D leg (uses production <code>couplingSplit.js</code>; fails on non-finite coupling heads)</td><td>—</td><td><code>node verify-1d-split.mjs &lt;inp&gt; [--wasm &lt;p&gt;] [--tol &lt;%&gt;] [--hours &lt;n&gt;] [--json]</code></td></tr><tr><td><code>test-gpu-worker.mjs</code></td><td>Drives the production <code>gpu2dWorker.js</code> through the app&#39;s <code>run2d</code> contract in headed Chrome</td><td>CDP 9224</td><td><code>node test-gpu-worker.mjs [--inp &lt;p&gt;]</code></td></tr><tr><td><code>bench-gpu-coupl.mjs</code></td><td>Per-window GPU split timings (<code>strideMs/freezeMs/advanceMs/exchMs/dt0/substeps</code>), extrapolates 48 h wall time</td><td>CDP 9225</td><td><code>node bench-gpu-coupl.mjs [--windows N] [--lts N] [--cadence N] [--dtfloor N] [--dbgcell N] [--inp &lt;p&gt;]</code></td></tr><tr><td><code>run-webgpu-harness.mjs</code></td><td>Drives <code>public/webgpu/harness.html</code> M1/M2 parity + bench in <strong>headed</strong> Chrome (headless has no WebGPU); stages fixtures into <code>public/webgpu/fixtures/</code> from <code>scripts/verify-out/</code></td><td>CDP 9223</td><td><code>node run-webgpu-harness.mjs [fixture…] [--coupled] [--bench] [--lts N] [--hours N]</code></td></tr><tr><td><code>test-2d-render.mjs</code></td><td>Render-pipeline smoke test: velocity arrows, contour bands regression, robust frame-max, WebGL2 shader compile, <code>display2DResults</code> finiteness</td><td>CDP 9225</td><td>no args</td></tr></tbody></table><h2 id="build-scripts" tabindex="-1">Build scripts <a class="header-anchor" href="#build-scripts" aria-label="Permalink to &quot;Build scripts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Purpose</th><th>Usage</th></tr></thead><tbody><tr><td><code>build-openswmm2d.sh</code></td><td>Linux/macOS WASM build (emcmake + vcpkg)</td><td><code>npm run build:2d-wasm:sh</code></td></tr><tr><td><code>build-openswmm2d.ps1</code></td><td>Windows WASM build</td><td><code>npm run build:2d-wasm</code></td></tr></tbody></table><h2 id="fixtures-note" tabindex="-1">Fixtures note <a class="header-anchor" href="#fixtures-note" aria-label="Permalink to &quot;Fixtures note&quot;">​</a></h2><blockquote><p><strong>Note:</strong> <code>public/webgpu/fixtures/</code> is <strong>not committed</strong> — the harness scripts generate/stage it from <code>scripts/verify-out/</code>. If a fixture is missing, run the generator first (<code>make-marcher-*.mjs</code>) or <code>verify-bellinge.mjs</code>.</p></blockquote>',13)])])}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
